<?php
declare(strict_types=1);

date_default_timezone_set('America/New_York');

$root = dirname(__DIR__);
$target = __DIR__.'/install_admin_paid_payouts_dashboard_v006_20261117_021900am.php';
$B64 = '';
$SHA = '18d2c371c600bcc515ba1c5ec946b46a22af54feda1db531e83d89ffefad2b8a';

function lg_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function lg_lint(string $path): array {
    $out = trim((string)@shell_exec('php -l '.escapeshellarg($path).' 2>&1'));
    return [strpos($out, 'No syntax errors detected') !== false, $out];
}

$checks = [];
$checks[] = ['LINTGATE running from /public_html/_installers', realpath(__DIR__) === realpath($root.'/_installers'), __DIR__];

$data = base64_decode($B64, true);
$checks[] = ['Embedded installer decoded', is_string($data), is_string($data) ? strlen($data).' bytes' : 'decode failed'];

if (is_string($data)) {
    $checks[] = ['Embedded installer SHA-256 verified', hash('sha256', $data) === $SHA, hash('sha256', $data)];

    if (@file_put_contents($target, $data, LOCK_EX) !== false) {
        @chmod($target, 0644);
        $checks[] = ['Real installer staged', true, $target];

        list($ok, $detail) = lg_lint($target);
        $checks[] = ['Real installer php -l', $ok, $detail];
    } else {
        $checks[] = ['Real installer staged', false, $target];
    }
}

$all = true;
foreach ($checks as $c) {
    if (!$c[1]) $all = false;
}
?>
